CREATE OR REPLACE FUNCTION public.confirm_verified_mall_payment(p_session text, p_payment text, p_amount bigint, p_live boolean, p_paid_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE pc public.mall_payment_checkout%ROWTYPE;r public.contract_payment_request%ROWTYPE;q public.onboarding_quote%ROWTYPE;reason text;
BEGIN
 SELECT * INTO STRICT pc FROM public.mall_payment_checkout WHERE session_id=p_session;
 SELECT * INTO STRICT r FROM public.contract_payment_request WHERE request_id=pc.request_id;
 IF r.pricing_model<>'v3' THEN PERFORM app_private.confirm_verified_mall_payment_before_v3(p_session,p_payment,p_amount,p_live,p_paid_at);RETURN;END IF;
 -- Match fulfillment and request creation: lock the mall before its payment rows.
 PERFORM 1 FROM public.mall WHERE mall_id=r.mall_id FOR UPDATE;
 SELECT * INTO STRICT r FROM public.contract_payment_request WHERE request_id=pc.request_id FOR UPDATE;
 SELECT * INTO STRICT pc FROM public.mall_payment_checkout WHERE session_id=p_session FOR UPDATE;
 IF pc.amount_cent<>p_amount OR r.amount_cent<>p_amount OR pc.livemode<>p_live OR p_live OR p_paid_at IS NULL OR p_payment IS NULL OR p_amount IS NULL OR p_live IS NULL OR p_payment !~ '^pay_[A-Za-z0-9]+$' THEN RAISE EXCEPTION 'Payment does not match the test checkout.'; END IF;
 IF pc.payment_id IS NOT NULL THEN IF pc.payment_id<>p_payment THEN RAISE EXCEPTION 'Checkout already paid.'; END IF;RETURN;END IF;
 reason:=app_private.v3_subscription_payment_issue(r,p_paid_at);
 IF r.status<>'pending' THEN reason:='Payment arrived for a cancelled or superseded request.'; END IF;
 IF r.fee_type='onboarding' THEN
  SELECT * INTO STRICT q FROM public.onboarding_quote WHERE quote_id=r.quote_id;
  IF q.status<>'finalized' OR q.expires_at<p_paid_at THEN reason:='Payment arrived for an expired or superseded quote.';END IF;
 END IF;
 UPDATE public.mall_payment_checkout SET payment_id=p_payment,confirmed_at=now() WHERE request_id=r.request_id;
 UPDATE public.contract_payment_request SET status='paid',payment_reference=p_payment,paymongo_payment_id=p_payment,paid_at=p_paid_at,reconciliation_reason=reason WHERE request_id=r.request_id;
 IF reason IS NULL THEN PERFORM public.fulfill_v3_payment(r.request_id);END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.fulfill_v3_payment(p_request bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.contract_payment_request%ROWTYPE;c public.contract%ROWTYPE;id bigint;starts timestamptz;actor bigint;
BEGIN
 SELECT * INTO STRICT r FROM public.contract_payment_request WHERE request_id=p_request;
 PERFORM 1 FROM public.mall WHERE mall_id=r.mall_id FOR UPDATE;
 SELECT * INTO STRICT r FROM public.contract_payment_request WHERE request_id=p_request FOR UPDATE;
 IF r.pricing_model<>'v3' OR r.status<>'paid' OR r.reconciliation_reason IS NOT NULL THEN RAISE EXCEPTION 'Verified payment required.'; END IF;
 IF r.fulfilled_at IS NOT NULL THEN RETURN jsonb_build_object('fulfilled',true); END IF;
 actor:=(r.details->>'actor_id')::bigint;
 BEGIN
  IF r.fee_type='onboarding' THEN
   UPDATE public.onboarding_quote SET status='paid' WHERE quote_id=r.quote_id;
  ELSIF r.fee_type='subscription' THEN
   PERFORM public.workflow_action((r.details->>'application_id')::bigint,actor,'publish');
  ELSIF r.fee_type IN ('upgrade','renewal','reinstatement') THEN
   SELECT * INTO STRICT c FROM public.contract WHERE contract_id=(r.details->>'previous_contract_id')::bigint FOR UPDATE;
   IF NOT c.contract_is_current THEN RAISE EXCEPTION 'Contract changed before payment. Reconciliation required.'; END IF;
   IF r.fee_type='upgrade' THEN
    IF c.contract_end<=now() THEN RAISE EXCEPTION 'Upgrade payment arrived after expiry.'; END IF;
    id:=app_private.create_v3_contract(r.mall_id,actor,r.details->'tier',c.capacity_snapshot,c.contract_onboarding_fee::numeric,now(),c.contract_end,'upgrade',c.contract_id,COALESCE(c.allowance_start,c.contract_start),COALESCE(c.allowance_end,c.contract_end));
   ELSE
    starts:=CASE WHEN r.fee_type='reinstatement' THEN GREATEST((r.details->>'start')::timestamptz,r.paid_at) ELSE (r.details->>'start')::timestamptz END;
    UPDATE public.contract SET scheduled=false,contract_status='superseded' WHERE mall_id=r.mall_id AND scheduled AND change_type='downgrade';
    id:=app_private.create_v3_contract(r.mall_id,actor,r.details->'tier',c.capacity_snapshot,c.contract_onboarding_fee::numeric,starts,starts+interval '1 year',r.fee_type,c.contract_id,starts,starts+interval '1 year',starts>now());
   END IF;
   UPDATE public.contract_payment_request SET contract_id=id WHERE request_id=r.request_id;
  ELSIF r.fee_type IN ('stall_addon','map_update') THEN
   UPDATE public.mall_service_request SET status='queued',queued_at=now() WHERE payment_request_id=r.request_id AND status='awaiting_payment';
   IF NOT FOUND THEN RAISE EXCEPTION 'Service request changed. Reconciliation required.'; END IF;
   UPDATE public.stall_application SET s_application_status='approved',s_application_updated_at=now() WHERE s_application_id IN (SELECT stall_application_id FROM public.mall_service_request WHERE payment_request_id=r.request_id AND kind='stall_addon');
  END IF;
  UPDATE public.contract_payment_request SET fulfilled_at=now(),fulfillment_error=NULL WHERE request_id=r.request_id;
 EXCEPTION WHEN OTHERS THEN
  UPDATE public.contract_payment_request SET fulfillment_error='Payment received; fulfillment needs retry or Super Admin review.' WHERE request_id=r.request_id;
  RETURN jsonb_build_object('fulfilled',false,'message','Payment received; fulfillment needs retry or Super Admin review.');
 END;
 RETURN jsonb_build_object('fulfilled',true);
END $function$;

CREATE OR REPLACE FUNCTION public.workflow_action(p_id bigint, p_actor bigint, p_action text, p_text text DEFAULT ''::text, p_target text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.application%ROWTYPE;s public.mall_onboarding%ROWTYPE;r public.contract_payment_request%ROWTYPE;q public.onboarding_quote%ROWTYPE;c bigint;result jsonb;d public.ar_development%ROWTYPE;
BEGIN
 SELECT * INTO STRICT a FROM public.application WHERE application_id=p_id;
 PERFORM 1 FROM public.mall WHERE mall_id=a.mall_id FOR UPDATE;
 SELECT * INTO s FROM public.mall_onboarding WHERE mall_id=a.mall_id;
 IF s.pricing_model='v3' AND p_action='accept' AND a.application_version>1 AND NOT EXISTS(SELECT 1 FROM public.mall_service_request WHERE application_id=p_id AND kind='map_update' AND status IN ('queued','in_progress')) THEN RAISE EXCEPTION 'Approve the map-update fee or free allowance before accepting the application.';END IF;
 IF s.pricing_model='v3' AND p_action='ar_status' AND p_target='node_mapping' THEN
  SELECT * INTO d FROM public.ar_development WHERE application_id=p_id ORDER BY ar_development_id DESC LIMIT 1;
  IF d.ar_development_status='pending' AND a.application_version=1 AND EXISTS(SELECT 1 FROM public.ar_development other JOIN public.application ap USING(application_id) WHERE ap.application_version=1 AND other.ar_development_status='pending' AND (other.ar_development_created_at,other.ar_development_id)<(d.ar_development_created_at,d.ar_development_id)) THEN RAISE EXCEPTION 'Start the earlier initial AR build first.';END IF;
  IF d.ar_development_status='pending' AND a.application_version>1 AND NOT EXISTS(SELECT 1 FROM public.mall_service_request WHERE application_id=p_id AND status='in_progress') THEN RAISE EXCEPTION 'Start the paid map-update service from its queue first.';END IF;
 END IF;
 IF s.pricing_model='v3' AND p_action='publish' THEN
  SELECT * INTO d FROM public.ar_development WHERE application_id=p_id ORDER BY ar_development_id DESC LIMIT 1;
  IF d.ar_development_status='live' THEN RETURN jsonb_build_object('published',true); END IF;
  IF a.application_version=1 THEN
   SELECT * INTO r FROM public.contract_payment_request WHERE mall_id=a.mall_id AND pricing_model='v3' AND fee_type='subscription' AND status='paid' AND reconciliation_reason IS NULL AND (details->>'application_id')::bigint=p_id ORDER BY request_id DESC LIMIT 1 FOR UPDATE;
   IF r.request_id IS NULL THEN RAISE EXCEPTION 'Verified first annual payment is required.'; END IF;
  ELSE
   IF NOT EXISTS(SELECT 1 FROM public.contract WHERE mall_id=a.mall_id AND contract_is_current AND lower(contract_status)='active' AND contract_end>now()) THEN RAISE EXCEPTION 'An active subscription is required.'; END IF;
   IF NOT EXISTS(SELECT 1 FROM public.mall_service_request WHERE application_id=p_id AND kind='map_update' AND status IN ('queued','in_progress')) THEN RAISE EXCEPTION 'Approved map update payment or allowance is required.'; END IF;
  END IF;
 END IF;
 result:=app_private.workflow_action_before_v3(p_id,p_actor,p_action,p_text,p_target);
 IF s.pricing_model='v3' AND p_action='publish' AND a.application_version=1 THEN
  SELECT * INTO STRICT q FROM public.onboarding_quote WHERE quote_id=s.quote_id;
  c:=app_private.create_v3_contract(a.mall_id,p_actor,r.details->'tier',q.capacity,q.amount_cent/100.0,now(),now()+interval '1 year','initial');
  UPDATE public.mall_onboarding SET contract_id=c WHERE mall_id=a.mall_id;
  UPDATE public.contract_payment_request SET contract_id=c,fulfilled_at=now(),fulfillment_error=NULL WHERE request_id=r.request_id;
 ELSIF s.pricing_model='v3' AND p_action='publish' THEN
  UPDATE public.mall_service_request SET status='completed',completed_at=now() WHERE application_id=p_id AND kind='map_update' AND status IN ('queued','in_progress');
 END IF;
 RETURN result;
END $function$;

CREATE OR REPLACE FUNCTION public.workflow_event(p_app bigint, p_actor bigint, p_action text, p_message text, p_ar bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE m bigint; r text; BEGIN
 SELECT mall_id INTO STRICT m FROM public.application WHERE application_id=p_app;
 SELECT admin_role INTO STRICT r FROM public.admin WHERE admin_id=p_actor AND NOT admin_is_deactivated;
 INSERT INTO public.audit_log(audit_log_module,audit_log_action,audit_log_details,audit_log_performed_at,audit_log_performed_by,mall_id)
 VALUES('application_ar',p_action,p_message,now(),p_actor,m);
 INSERT INTO public.admin_notification(admin_notif_type,admin_notif_title,admin_notif_message,admin_notif_action_url,admin_notif_action_label,
 admin_notif_source_type,admin_notif_source_id,admin_notif_source_label,admin_notif_actor_id,admin_notif_actor_role,admin_id,mall_id,admin_notif_created_at,admin_notif_is_read,admin_notif_is_archived)
 SELECT 'workflow_status','NavAR workflow update',p_message,
 CASE WHEN p_ar IS NULL THEN '/application-management?applicationId='||p_app ELSE '/ar-development?projectId='||p_ar END,'View details',
 'application_ar',coalesce(p_ar,p_app),'Version update',p_actor,r,a.admin_id,m,now(),false,false
 FROM public.admin a WHERE NOT a.admin_is_deactivated AND a.admin_account_status='official'
 AND ((r='super_admin' AND a.admin_role='mall_admin' AND a.mall_id=m) OR (r='mall_admin' AND a.admin_role='super_admin'));
END $function$;

CREATE OR REPLACE FUNCTION app_private.activate_verified_subscription()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE started timestamptz;
BEGIN IF NEW.pricing_model='v3' THEN RETURN NEW; END IF;
 IF NEW.paid_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.mall_payment_checkout pc
  WHERE pc.request_id=NEW.request_id AND pc.payment_id=NEW.payment_reference AND pc.confirmed_at IS NOT NULL) THEN
  RAISE EXCEPTION 'A registered verified checkout is required to activate a subscription.';
 END IF;
 IF NEW.fee_type='onboarding' THEN started:=NEW.paid_at;
 ELSE
  SELECT min(r.paid_at) INTO started FROM public.contract_payment_request r
   JOIN public.mall_payment_checkout pc ON pc.request_id=r.request_id AND pc.payment_id=r.payment_reference AND pc.confirmed_at IS NOT NULL
   WHERE r.contract_id=NEW.contract_id AND r.fee_type='onboarding' AND r.status='paid';
  IF started IS NULL THEN RAISE EXCEPTION 'A verified onboarding payment is required before the annual fee can be settled.'; END IF;
 END IF;
 -- Annual settlement does not restart the term or lift a suspension.
 UPDATE public.contract SET contract_start=started,contract_end=started+interval '1 year',
  contract_status=CASE WHEN lower(contract_status) IN ('suspended','terminated','cancelled','expired') THEN contract_status
   WHEN started+interval '1 year'<=now() THEN 'expired' ELSE 'active' END,contract_updated_at=now()
 WHERE contract_id=NEW.contract_id AND contract_is_current;
 RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION app_private.create_v3_contract(p_mall bigint, p_actor bigint, p_tier jsonb, p_capacity jsonb, p_onboarding numeric, p_start timestamp with time zone, p_end timestamp with time zone, p_change text, p_previous bigint DEFAULT NULL::bigint, p_allowance_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_allowance_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scheduled boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE id bigint;v integer;
BEGIN
 PERFORM 1 FROM public.mall WHERE mall_id=p_mall FOR UPDATE;
 SELECT COALESCE(max(contract_version),0)+1 INTO v FROM public.contract WHERE mall_id=p_mall;
 IF NOT p_scheduled THEN UPDATE public.contract SET contract_is_current=false WHERE mall_id=p_mall AND contract_is_current; END IF;
 INSERT INTO public.contract(contract_version,contract_is_current,contract_annual_fee,contract_onboarding_fee,contract_grace_period_days,contract_reinstatement_rate,contract_start,contract_end,contract_created_at,contract_updated_at,admin_id,s_tier_id,mall_id,contract_status,contract_map_updates_per_year,pricing_model,tier_snapshot,capacity_snapshot,change_type,previous_contract_id,allowance_start,allowance_end,scheduled)
 VALUES(v,NOT p_scheduled,(p_tier->>'s_tier_annual_fee')::numeric,p_onboarding,(p_tier->>'s_tier_grace_period_days')::integer,(p_tier->>'s_tier_reinstatement_rate')::numeric,p_start,p_end,now(),now(),p_actor,(p_tier->>'s_tier_id')::bigint,p_mall,CASE WHEN p_scheduled THEN 'scheduled' ELSE 'active' END,(p_tier->>'s_tier_map_updates_per_year')::integer,'v3',p_tier,p_capacity,p_change,p_previous,COALESCE(p_allowance_start,p_start),COALESCE(p_allowance_end,p_end),p_scheduled) RETURNING contract_id INTO id;
 RETURN id;
END $function$;

CREATE OR REPLACE FUNCTION app_private.enforce_ar_release()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE mall bigint; c public.contract%ROWTYPE;
BEGIN
 IF lower(NEW.ar_development_status) NOT IN ('ready','live') THEN RETURN NEW; END IF;
 IF NOT app_private.application_requirements_ready(NEW.application_id) THEN
  RAISE EXCEPTION 'Approve the application and complete every profile, floor plan, scale, route and entry-point requirement before marking AR ready.';
 END IF;
 IF lower(NEW.ar_development_status)='live' THEN
  SELECT mall_id INTO mall FROM public.application WHERE application_id=NEW.application_id;
  IF (SELECT count(*) FROM public.contract WHERE mall_id=mall AND contract_is_current)<>1 THEN RAISE EXCEPTION 'Exactly one current contract is required.'; END IF;
  SELECT * INTO c FROM public.contract WHERE mall_id=mall AND contract_is_current;
  IF NOT COALESCE(lower(c.contract_status) IN ('active','grace') AND now()>=c.contract_start
   AND now()<c.contract_end+CASE WHEN lower(c.contract_status)='grace' THEN make_interval(days=>c.contract_grace_period_days) ELSE interval '0 days' END,false) THEN
   RAISE EXCEPTION 'An active subscription is required before AR goes live.';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.contract_payment_request r JOIN public.mall_payment_checkout pc USING(request_id)
   WHERE r.contract_id=c.contract_id AND r.fee_type='subscription' AND r.status='paid'
    AND r.confirmed_at IS NOT NULL AND length(trim(r.confirmation_message))>0
    AND pc.payment_id=r.payment_reference AND pc.confirmed_at IS NOT NULL) THEN
   RAISE EXCEPTION 'Confirm AR readiness and verify the subscription payment before activation.';
  END IF;
 END IF;
 RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION app_private.guard_onboarding_checkout_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.contract_payment_request%ROWTYPE; c public.contract%ROWTYPE;
 s public.mall_onboarding%ROWTYPE; mid bigint; snapshot jsonb;
BEGIN
 SELECT contract.mall_id INTO mid FROM public.contract_payment_request request
 JOIN public.contract contract USING(contract_id) WHERE request.request_id=NEW.request_id;
 PERFORM pg_advisory_xact_lock(mid);
 SELECT * INTO STRICT r FROM public.contract_payment_request WHERE request_id=NEW.request_id FOR UPDATE;
 IF r.fee_type<>'onboarding' THEN RETURN NEW; END IF;
 SELECT * INTO STRICT c FROM public.contract WHERE contract_id=r.contract_id;
 SELECT * INTO STRICT s FROM public.mall_onboarding WHERE mall_id=c.mall_id;
 snapshot:=jsonb_build_object('terms',s.offer,'contract_id',c.contract_id,
 'onboarding_fee',c.contract_onboarding_fee,'annual_fee',c.contract_annual_fee,
 'start',c.contract_start,'end',c.contract_end,
 'tier',(SELECT to_jsonb(t) FROM public.subscription_tier t WHERE t.s_tier_id=c.s_tier_id));
 IF r.status<>'pending' OR NOT c.contract_is_current OR s.contract_id IS DISTINCT FROM c.contract_id
 OR s.completed_at IS NOT NULL OR NEW.amount_cent<>round(c.contract_onboarding_fee::numeric*100)::bigint
 OR s.prepayment_acceptance->>'fingerprint' IS DISTINCT FROM md5(snapshot::text) THEN
  RAISE EXCEPTION 'The offer changed. Reload and accept the current terms before checkout.';
 END IF;
 RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION app_private.prepare_v3_payment_before_cancellation(p_fee text, p_target_tier text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a public.admin%ROWTYPE;s public.mall_onboarding%ROWTYPE;c public.contract%ROWTYPE;t jsonb;r public.contract_payment_request%ROWTYPE;q public.onboarding_quote%ROWTYPE;d public.ar_development%ROWTYPE;amount bigint;details jsonb;days integer;
BEGIN
 a:=app_private.onboarding_admin();PERFORM 1 FROM public.mall WHERE mall_id=a.mall_id FOR UPDATE;
 SELECT * INTO STRICT s FROM public.mall_onboarding WHERE mall_id=a.mall_id;
 SELECT * INTO r FROM public.contract_payment_request WHERE mall_id=a.mall_id AND pricing_model='v3' AND fee_type=p_fee AND status='pending';
 IF FOUND THEN
  IF p_target_tier IS NOT NULL AND r.details->'tier'->>'s_tier_key' IS DISTINCT FROM p_target_tier THEN RAISE EXCEPTION 'Resolve the existing payment request first.'; END IF;
  RETURN to_jsonb(r);
 END IF;
 SELECT * INTO c FROM public.contract WHERE mall_id=a.mall_id AND contract_is_current FOR UPDATE;
 SELECT * INTO q FROM public.onboarding_quote WHERE quote_id=s.quote_id;
 t:=app_private.v3_tier(COALESCE(p_target_tier,s.selected_tier_key,c.tier_snapshot->>'s_tier_key'));
 IF t IS NULL THEN RAISE EXCEPTION 'Choose a valid subscription tier.'; END IF;
 details:=jsonb_build_object('tier',t,'actor_id',a.admin_id);
 IF p_fee='subscription' THEN
  IF s.pricing_model<>'v3' OR s.completed_at IS NULL OR c.contract_id IS NOT NULL THEN RAISE EXCEPTION 'First subscription payment is unavailable.'; END IF;
  SELECT x.* INTO d FROM public.ar_development x JOIN public.application ap USING(application_id) WHERE ap.mall_id=a.mall_id AND ap.application_version=1 ORDER BY x.ar_development_id DESC LIMIT 1;
  IF d.ar_development_status IS DISTINCT FROM 'ready' OR d.ar_development_mall_approved_at IS NULL THEN RAISE EXCEPTION 'Confirm the Ready AR before paying the annual fee.'; END IF;
  IF EXISTS(SELECT 1 FROM public.contract_payment_request WHERE mall_id=a.mall_id AND fee_type='subscription' AND status='paid') THEN RAISE EXCEPTION 'Annual payment already recorded. Retry publication.'; END IF;
  amount:=(t->>'s_tier_annual_fee')::bigint*100;details:=details||jsonb_build_object('application_id',d.application_id);
 ELSIF p_fee='upgrade' THEN
  IF c.contract_id IS NULL OR lower(c.contract_status)<>'active' OR c.contract_end<=now() OR (t->>'s_tier_annual_fee')::numeric<=c.contract_annual_fee THEN RAISE EXCEPTION 'Choose a higher tier on an active subscription.'; END IF;
  days:=GREATEST(0,ceil(extract(epoch FROM c.contract_end-now())/86400))::integer;
  amount:=round(((t->>'s_tier_annual_fee')::numeric-c.contract_annual_fee)*days/365)*100;
  details:=details||jsonb_build_object('previous_contract_id',c.contract_id,'end',c.contract_end,'days_remaining',days);
 ELSIF p_fee IN ('renewal','reinstatement') THEN
  IF EXISTS(SELECT 1 FROM public.contract WHERE mall_id=a.mall_id AND previous_contract_id=c.contract_id AND scheduled AND change_type IN ('renewal','reinstatement')) THEN RAISE EXCEPTION 'A paid renewal is already scheduled.'; END IF;
  IF c.contract_id IS NULL OR c.contract_end>now()+interval '30 days' OR lower(c.contract_status) IN ('suspended','terminated','cancelled') THEN RAISE EXCEPTION 'Renewal is unavailable for this contract.'; END IF;
  IF p_fee='reinstatement' AND c.contract_end+make_interval(days=>c.contract_grace_period_days)>now() THEN RAISE EXCEPTION 'Reinstatement is not yet due.'; END IF;
  IF p_fee='renewal' AND c.contract_end+make_interval(days=>c.contract_grace_period_days)<now() THEN RAISE EXCEPTION 'Reinstatement is required after grace.'; END IF;
  SELECT tier_snapshot INTO t FROM public.contract WHERE mall_id=a.mall_id AND scheduled AND change_type='downgrade' ORDER BY contract_start LIMIT 1;
  t:=COALESCE(t,app_private.v3_tier(COALESCE(p_target_tier,c.tier_snapshot->>'s_tier_key')));
  amount:=round((t->>'s_tier_annual_fee')::numeric*(CASE WHEN p_fee='reinstatement' THEN 1+c.contract_reinstatement_rate ELSE 1 END))*100;
  details:=details||jsonb_build_object('tier',t,'previous_contract_id',c.contract_id,'start',CASE WHEN p_fee='reinstatement' THEN now() ELSE c.contract_end END);
 ELSE RAISE EXCEPTION 'Unsupported payment request.'; END IF;
 INSERT INTO public.contract_payment_request(contract_id,mall_id,quote_id,fee_type,amount_cent,pricing_model,details) VALUES(c.contract_id,a.mall_id,s.quote_id,p_fee,amount,'v3',details) RETURNING * INTO r;
 RETURN to_jsonb(r);
END $function$;

CREATE OR REPLACE FUNCTION app_private.v3_subscription_payment_issue(r contract_payment_request, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE c public.contract%ROWTYPE;
BEGIN
 IF r.fee_type NOT IN ('upgrade','renewal','reinstatement') THEN RETURN NULL; END IF;
 SELECT * INTO c FROM public.contract WHERE contract_id=(r.details->>'previous_contract_id')::bigint;
 IF c.contract_id IS NULL OR c.mall_id IS DISTINCT FROM r.mall_id OR NOT c.contract_is_current
    OR lower(c.contract_status) IN ('suspended','terminated','cancelled') THEN
  RETURN 'Subscription changed; payment requires reconciliation.';
 END IF;
 IF r.fee_type='upgrade' AND (lower(c.contract_status)<>'active' OR c.contract_end<=p_at OR c.contract_end IS DISTINCT FROM (r.details->>'end')::timestamptz) THEN
  RETURN 'Upgrade terms changed or expired; payment requires reconciliation.';
 END IF;
 IF r.fee_type='renewal' AND (c.contract_end+make_interval(days=>c.contract_grace_period_days)<p_at OR c.contract_end IS DISTINCT FROM (r.details->>'start')::timestamptz) THEN
  RETURN 'Renewal terms changed or grace expired; payment requires reconciliation.';
 END IF;
 IF EXISTS(SELECT 1 FROM public.contract WHERE mall_id=r.mall_id AND previous_contract_id=c.contract_id AND scheduled AND change_type IN ('renewal','reinstatement')) THEN
  RETURN 'A paid renewal is already scheduled; payment requires reconciliation.';
 END IF;
 RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION app_private.workflow_action_before_v3(p_id bigint, p_actor bigint, p_action text, p_text text DEFAULT ''::text, p_target text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE a public.application; d public.ar_development; who public.admin; c public.contract; new_status text; thread_id_value bigint; other public.ar_development; BEGIN
 SELECT * INTO STRICT who FROM public.admin WHERE admin_id=p_actor AND NOT admin_is_deactivated AND admin_account_status='official';
 IF who.admin_role NOT IN ('super_admin','mall_admin') THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT a FROM public.application WHERE application_id=p_id;
 PERFORM 1 FROM public.mall WHERE mall_id=a.mall_id FOR UPDATE;
 SELECT * INTO STRICT a FROM public.application WHERE application_id=p_id FOR UPDATE;
 IF who.admin_role='mall_admin' AND who.mall_id IS DISTINCT FROM a.mall_id THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 IF EXISTS(SELECT 1 FROM public.application x WHERE x.mall_id=a.mall_id AND (x.application_version,x.application_attempt)>(a.application_version,a.application_attempt)) THEN RAISE EXCEPTION 'Older versions are read-only' USING ERRCODE='P0001'; END IF;
 SELECT * INTO d FROM public.ar_development WHERE application_id=p_id ORDER BY ar_development_id DESC LIMIT 1 FOR UPDATE;
 IF d.ar_development_status IN ('live','unpublished') THEN RAISE EXCEPTION 'Published versions are read-only' USING ERRCODE='P0001'; END IF;
 IF p_action IN ('accept','reject','approve','revision','ar_status') AND who.admin_role<>'super_admin' THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 IF p_action IN ('dispute','resubmit','mall_approve') AND who.admin_role<>'mall_admin' THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF;
 IF p_action='accept' THEN
  IF a.application_version<2 OR a.application_status NOT IN ('pending','disputed') THEN RAISE EXCEPTION 'Request cannot be accepted'; END IF;
  SELECT * INTO c FROM public.contract WHERE mall_id=a.mall_id AND contract_is_current FOR UPDATE;
  IF FOUND AND (c.contract_start IS NULL OR c.contract_end IS NULL) THEN RAISE EXCEPTION 'Contract term is required for quota accounting'; END IF;
  IF c.pricing_model<>'v3' AND c.contract_map_updates_per_year IS NOT NULL AND (
   SELECT count(*) FROM public.application WHERE mall_id=a.mall_id AND application_version>1
   AND application_accepted_at>=c.contract_start AND application_accepted_at<c.contract_end)>=c.contract_map_updates_per_year THEN RAISE EXCEPTION 'No map updates left'; END IF;
  UPDATE public.application SET application_status='submitted',application_accepted_at=now(),application_updated_at=now() WHERE application_id=p_id;
 ELSIF p_action='reject' THEN
  IF a.application_version<2 OR a.application_status NOT IN ('pending','disputed') OR length(trim(p_text))=0 THEN RAISE EXCEPTION 'Rejection requires a pending/disputed v2+ request and explanation'; END IF;
  UPDATE public.application SET application_status=CASE WHEN application_dispute_count=2 THEN 'rejected_final' ELSE 'rejected' END,application_updated_at=now() WHERE application_id=p_id;
 ELSIF p_action='dispute' THEN
  IF a.application_status<>'rejected' OR a.application_version<2 OR a.application_dispute_count>=2 OR length(trim(p_text))=0 THEN RAISE EXCEPTION 'Dispute not allowed'; END IF;
  UPDATE public.application SET application_status='disputed',application_dispute_count=application_dispute_count+1,application_updated_at=now() WHERE application_id=p_id;
 ELSIF p_action='resubmit' THEN
  IF a.application_status NOT IN ('draft','for_revision') THEN RAISE EXCEPTION 'Resubmission not allowed'; END IF;
  UPDATE public.application SET application_status='submitted',application_updated_at=now() WHERE application_id=p_id;
 ELSIF p_action='revision' THEN
  IF a.application_status NOT IN ('submitted','approved') OR (a.application_status='approved' AND coalesce(d.ar_development_status,'') NOT IN ('pending','node_mapping','testing'))
  OR d.ar_development_mall_approved_at IS NOT NULL OR d.ar_development_ready_at IS NOT NULL THEN RAISE EXCEPTION 'Revision not allowed once AR has reached Ready'; END IF;
  UPDATE public.application SET application_status='for_revision',application_updated_at=now() WHERE application_id=p_id;
  IF a.application_status='approved' THEN
   UPDATE public.ar_development SET ar_development_resume_status=ar_development_status,ar_development_status='on_hold',ar_development_updated_at=now() WHERE ar_development_id=d.ar_development_id;
   PERFORM public.workflow_event(p_id,p_actor,'on_hold','AR: '||d.ar_development_status||' -> on_hold',d.ar_development_id);
  END IF;
 ELSIF p_action='approve' THEN
  IF a.application_status NOT IN ('submitted','for_revision') THEN RAISE EXCEPTION 'Only submitted or For Revision applications can be approved'; END IF;
  UPDATE public.application SET application_status='approved',application_updated_at=now() WHERE application_id=p_id;
  IF d.ar_development_id IS NULL THEN
   INSERT INTO public.ar_development(application_id,ar_development_version,ar_development_status,ar_development_created_at,ar_development_updated_at)
   VALUES(p_id,a.application_version,'pending',now(),now()) RETURNING * INTO d;
   PERFORM public.workflow_event(p_id,p_actor,'ar_created','AR: pending',d.ar_development_id);
  ELSIF d.ar_development_status='on_hold' THEN
   UPDATE public.ar_development SET ar_development_status=ar_development_resume_status,ar_development_resume_status=NULL,ar_development_updated_at=now() WHERE ar_development_id=d.ar_development_id;
   PERFORM public.workflow_event(p_id,p_actor,'ar_resumed','AR resumed: '||d.ar_development_resume_status,d.ar_development_id);
  ELSE RAISE EXCEPTION 'Existing AR is not On Hold'; END IF;
 ELSIF p_action='ar_status' THEN
  IF a.application_status<>'approved' OR d.ar_development_mall_approved_at IS NOT NULL OR NOT (
   (d.ar_development_status='pending' AND p_target='node_mapping') OR
   (d.ar_development_status='node_mapping' AND p_target='testing') OR
   (d.ar_development_status='testing' AND p_target IN ('node_mapping','ready')) OR
   (d.ar_development_status='ready' AND p_target IN ('testing','node_mapping'))) THEN RAISE EXCEPTION 'AR transition not allowed'; END IF;
  UPDATE public.ar_development SET ar_development_status=p_target,ar_development_updated_at=now(),
   ar_development_ready_at=CASE WHEN p_target='ready' THEN now() ELSE ar_development_ready_at END,
   ar_development_reminder_count=CASE WHEN p_target='ready' THEN 0 ELSE ar_development_reminder_count END WHERE ar_development_id=d.ar_development_id;
  IF p_target='ready' THEN
   INSERT INTO public.thread(thread_source,thread_created_at,ar_development_id) SELECT 'ar_development',now(),d.ar_development_id WHERE NOT EXISTS(SELECT 1 FROM public.thread WHERE ar_development_id=d.ar_development_id);
  END IF;
 ELSIF p_action='mall_approve' THEN
  IF d.ar_development_status<>'ready' OR p_text<>'acknowledged' OR d.ar_development_mall_approved_at IS NOT NULL THEN RAISE EXCEPTION 'Ready approval requires acknowledgement'; END IF;
  UPDATE public.ar_development SET ar_development_mall_approved_at=now(),ar_development_updated_at=now() WHERE ar_development_id=d.ar_development_id;
 ELSIF p_action='publish' THEN
  IF d.ar_development_status<>'ready' OR d.ar_development_mall_approved_at IS NULL THEN RAISE EXCEPTION 'Mall approval is required'; END IF;
  FOR other IN SELECT x.* FROM public.ar_development x JOIN public.application y USING(application_id)
   WHERE y.mall_id=a.mall_id AND x.ar_development_status='live' AND x.ar_development_id<>d.ar_development_id FOR UPDATE OF x LOOP
   UPDATE public.ar_development SET ar_development_status='unpublished',ar_development_unpublish_reason='superseded',ar_development_updated_at=now() WHERE ar_development_id=other.ar_development_id;
   PERFORM public.workflow_event(other.application_id,p_actor,'superseded','AR unpublished: superseded',other.ar_development_id);
  END LOOP;
  UPDATE public.ar_development SET ar_development_status='live',ar_development_activated_at=now(),ar_development_updated_at=now() WHERE ar_development_id=d.ar_development_id;
 ELSE RAISE EXCEPTION 'Unknown workflow action'; END IF;
 IF length(trim(p_text))>0 AND p_action IN ('reject','dispute','revision') THEN
  INSERT INTO public.thread(thread_source,thread_created_at,application_id) SELECT 'development_application',now(),p_id WHERE NOT EXISTS(SELECT 1 FROM public.thread WHERE application_id=p_id);
  SELECT thread_id INTO STRICT thread_id_value FROM public.thread WHERE application_id=p_id ORDER BY thread_id LIMIT 1;
  INSERT INTO public.thread_message(message_sender_type,message_sent_at,message_content,thread_id,message_sender)
   VALUES(CASE WHEN who.admin_role='super_admin' THEN 'admin' ELSE 'mall_admin' END,now(),p_text,thread_id_value,p_actor);
 END IF;
 SELECT application_status INTO new_status FROM public.application WHERE application_id=p_id;
 PERFORM public.workflow_event(p_id,p_actor,p_action,CASE WHEN p_action='ar_status' THEN 'AR: '||d.ar_development_status||' -> '||p_target ELSE 'Application '||a.application_version||': '||p_action||' ('||new_status||') AR #'||coalesce(d.ar_development_id::text,'none') END,
 CASE WHEN p_action IN ('ar_status','mall_approve','publish') THEN d.ar_development_id ELSE NULL END);
 RETURN jsonb_build_object('applicationId',p_id,'arDevelopmentId',d.ar_development_id,'status',new_status);
END $function$;
